import { hmacSha256 } from './hmac.mjs';
import { b64urlEncodeString, b64urlDecodeToString, b64urlEncode } from './base64url.mjs';
import { dumps } from './pyjson.mjs';

const te = new TextEncoder();

export class JWTError extends Error {}

export function encode(payload, key) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const headerB64 = b64urlEncodeString(dumps(header));
  const payloadB64 = b64urlEncodeString(dumps(payload));
  const signingInput = headerB64 + '.' + payloadB64;
  const sig = hmacSha256(te.encode(key), te.encode(signingInput));
  return signingInput + '.' + b64urlEncode(sig);
}

export function decode(token, key, { options = {}, algorithms = ['HS256'] } = {}) {
  const parts = token.split('.');
  if (parts.length !== 3) throw new JWTError('Not enough segments');
  const [headerB64, payloadB64, sigB64] = parts;
  // verify alg
  const header = JSON.parse(b64urlDecodeToString(headerB64));
  if (!algorithms.includes(header.alg)) throw new JWTError('The specified alg value is not allowed');
  if (options.verify_signature !== false) {
    const expected = hmacSha256(te.encode(key), te.encode(headerB64 + '.' + payloadB64));
    const actual = b64urlDecode(sigB64);
    if (!timingSafeEqual(expected, actual)) throw new JWTError('Signature verification failed.');
  }
  const claims = JSON.parse(b64urlDecodeToString(payloadB64));
  if ('iat' in claims && options.verify_iat) validateIat(claims);
  return claims;
}
```

