function rotr(x, n) {
  return (x >>> n) | (x << (32 - n));
}

export function sha256(message) {
  const H = new Uint32Array([
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
    0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
  ]);

  const bitLenHi = Math.floor((message.length / 0x20000000)); // length / 2^29
  const bitLenLo = (message.length << 3) >>> 0;

  // Padded message: original || 0x80 || zeros || 64-bit big-endian bit length
  const paddedLen = Math.ceil((message.length + 9) / 64) * 64;
  const msg = new Uint8Array(paddedLen);
  msg.set(message);
  msg[message.length] = 0x80;
  const dv = new DataView(msg.buffer);
  dv.setUint32(paddedLen - 8, bitLenHi, false);
  dv.setUint32(paddedLen - 4, bitLenLo, false);

  const W = new Uint32Array(64);

  for (let off = 0; off < paddedLen; off += 64) {
    for (let t = 0; t < 16; t++) {
      W[t] = dv.getUint32(off + t * 4, false);
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }

    let a = H[0], b = H[1], c = H[2], d = H[3];
    let e = H[4], f = H[5], g = H[6], h = H[7];

    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = b; b = a; a = (temp1 + temp2) >>> 0;
    }

    H[0] = (H[0] + a) >>> 0;
    H[1] = (H[1] + b) >>> 0;
    H[2] = (H[2] + c) >>> 0;
    H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0;
    H[5] = (H[5] + f) >>> 0;
    H[6] = (H[6] + g) >>> 0;
    H[7] = (H[7] + h) >>> 0;
  }

  const digest = new Uint8Array(32);
  const out = new DataView(digest.buffer);
  for (let i = 0; i < 8; i++) {
    out.setUint32(i * 4, H[i], false);
  }
  return digest;
}

// HMAC-SHA256 (RFC 2104) built on the pure-JS SHA-256 in sha256.mjs.

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(key, message) {
  let k = key;
  if (k.length > BLOCK_SIZE) {
    k = sha256(k);
  }
  const paddedKey = new Uint8Array(BLOCK_SIZE);
  paddedKey.set(k);

  const ipad = new Uint8Array(BLOCK_SIZE + message.length);
  const opad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    ipad[i] = paddedKey[i] ^ 0x36;
    opad[i] = paddedKey[i] ^ 0x5c;
  }
  ipad.set(message, BLOCK_SIZE);

  const inner = sha256(ipad);
  const outer = new Uint8Array(BLOCK_SIZE + inner.length);
  outer.set(opad);
  outer.set(inner, BLOCK_SIZE);
  return sha256(outer);
}

// Base64url (RFC 4648 section 5) helpers, without padding,
// matching Python's base64.urlsafe_b64encode(...).rstrip(b"=").

const encoder = new TextEncoder();

export function b64urlEncode(bytes) {
  return Buffer.from(bytes)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

export function b64urlEncodeString(str) {
  return b64urlEncode(encoder.encode(str));
}

export function b64urlDecode(str) {
  let b64 = str.replace(/-/g, '+').replace(/_/g, '/');
  while (b64.length % 4 !== 0) {
    b64 += '=';
  }
  return new Uint8Array(Buffer.from(b64, 'base64'));
}

export function b64urlDecodeToString(str) {
  return Buffer.from(b64urlDecode(str)).toString('utf8');
}

// JSON serialization matching Python's json.dumps with defaults:
// ensure_ascii=True and compact separators (",", ":"), lowercase hex escapes.

export function dumpsString(s) {
  let out = '"';
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '"') {
      out += '\\"';
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (cp >= 0x20 && cp <= 0x7e) {
      out += ch;
    } else if (cp === 0x08) {
      out += '\\b';
    } else if (cp === 0x09) {
      out += '\\t';
    } else if (cp === 0x0a) {
      out += '\\n';
    } else if (cp === 0x0c) {
      out += '\\f';
    } else if (cp === 0x0d) {
      out += '\\r';
    } else if (cp < 0x10000) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      // Non-BMP: Python emits a UTF-16 surrogate pair of \uXXXX escapes.
      const v = cp - 0x10000;
      out += '\\u' + (0xd800 + (v >> 10)).toString(16);
      out += '\\u' + (0xdc00 + (v & 0x3ff)).toString(16);
    }
  }
  return out + '"';
}

function dumpsNumber(n) {
  if (Number.isInteger(n)) {
    return String(n);
  }
  return String(n);
}

export function dumps(value) {
  if (value === null || value === undefined) {
    return 'null';
  }
  if (value === true) {
    return 'true';
  }
  if (value === false) {
    return 'false';
  }
  if (typeof value === 'number') {
    return dumpsNumber(value);
  }
  if (typeof value === 'string') {
    return dumpsString(value);
  }
  if (Array.isArray(value)) {
    return '[' + value.map(dumps).join(',') + ']';
  }
  const parts = [];
  for (const [k, v] of Object.entries(value)) {
    parts.push(dumpsString(k) + ':' + dumps(v));
  }
  return '{' + parts.join(',') + '}';
}

// Python repr() emulation for the values printed by this program
// (dicts with string keys, string / int values).

// Python str.isprintable() excludes these general categories
// (except U+0020 SPACE, which is considered printable).
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Zl}\p{Zp}\p{Zs}]/u;

export function reprStr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  // Python prefers single quotes, switching to double quotes only when the
  // string contains a single quote but no double quote.
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (cp !== 0x20 && NON_PRINTABLE.test(ch)) {
      if (cp < 0x100) {
        out += '\\x' + cp.toString(16).padStart(2, '0');
      } else if (cp < 0x10000) {
        out += '\\u' + cp.toString(16).padStart(4, '0');
      } else {
        out += '\\U' + cp.toString(16).padStart(8, '0');
      }
    } else {
      out += ch;
    }
  }
  return out + quote;
}

export function reprValue(v) {
  if (typeof v === 'string') {
    return reprStr(v);
  }
  if (typeof v === 'number') {
    return String(v);
  }
  if (v === null || v === undefined) {
    return 'None';
  }
  if (typeof v === 'boolean') {
    return v ? 'True' : 'False';
  }
  if (Array.isArray(v)) {
    return '[' + v.map(reprValue).join(', ') + ']';
  }
  return reprDict(v);
}

export function reprDict(obj) {
  const parts = [];
  for (const [k, v] of Object.entries(obj)) {
    parts.push(reprStr(k) + ': ' + reprValue(v));
  }
  return '{' + parts.join(', ') + '}';
}

// Minimal JWT (HS256) implementation reproducing the observable behavior of
// python-jose's jwt.encode / jwt.decode for this program.
// HMAC-SHA256 is implemented in pure JS (see hmac.mjs / sha256.mjs).

import { hmacSha256 } from './hmac.mjs';
import { b64urlEncode, b64urlEncodeString, b64urlDecode, b64urlDecodeToString } from './base64url.mjs';
import { dumps } from './pyjson.mjs';

const encoder = new TextEncoder();

export class JWTError extends Error {}

export function encode(payload, key) {
  // python-jose emits the header with "alg" first, then "typ".
  const header = { alg: 'HS256', typ: 'JWT' };
  const signingInput = b64urlEncodeString(dumps(header)) + '.' + b64urlEncodeString(dumps(payload));
  const signature = hmacSha256(encoder.encode(key), encoder.encode(signingInput));
  return signingInput + '.' + b64urlEncode(signature);
}

function constantTimeEqual(a, b) {
  if (a.length !== b.length) {
    return false;
  }
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a[i] ^ b[i];
  }
  return diff === 0;
}

function validateIat(claims) {
  const iat = claims.iat;
  const ok =
    typeof iat === 'number'
      ? Number.isFinite(iat)
      : typeof iat === 'string' && iat.trim() !== '' && !Number.isNaN(Number(iat));
  if (!ok) {
    throw new JWTError('Issued At claim (iat) must be an integer.');
  }
}

export function decode(token, key, { options = {}, algorithms = ['HS256'] } = {}) {
  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new JWTError('Not enough segments');
  }
  const [headerB64, payloadB64, signatureB64] = parts;

  let header;
  try {
    header = JSON.parse(b64urlDecodeToString(headerB64));
  } catch {
    throw new JWTError('Invalid header string: must be a json object');
  }
  if (!algorithms.includes(header.alg)) {
    throw new JWTError('The specified alg value is not allowed');
  }

  if (options.verify_signature !== false) {
    const expected = hmacSha256(encoder.encode(key), encoder.encode(headerB64 + '.' + payloadB64));
    const actual = b64urlDecode(signatureB64);
    if (!constantTimeEqual(expected, actual)) {
      throw new JWTError('Signature verification failed.');
    }
  }

  const claims = JSON.parse(b64urlDecodeToString(payloadB64));

  if ('iat' in claims && options.verify_iat) {
    validateIat(claims);
  }

  return claims;
}

// Minimal emulation of Python's argparse for this program's CLI:
//   --data DATA            (required)
//   --verify_iat {true,false}  (required, restricted choices)
// Supports "--opt value" and "--opt=value" forms, -h/--help,
// argparse-style error messages on stderr, and exit code 2 on errors.

function basename(p) {
  const parts = p.split('/');
  return parts[parts.length - 1] || p;
}

const OPTION_SPECS = [
  { name: '--data', metavar: 'DATA', required: true, choices: null },
  { name: '--verify_iat', metavar: '{true,false}', required: true, choices: ['true', 'false'] },
];

function usageLine(prog) {
  const parts = OPTION_SPECS.map((s) => `${s.name} ${s.metavar}`);
  return `usage: ${prog} [-h] ${parts.join(' ')}`;
}

function printHelp(prog) {
  let out = usageLine(prog) + '\n\noptions:\n';
  out += '  -h, --help            show this help message and exit\n';
  for (const s of OPTION_SPECS) {
    out += `  ${s.name} ${s.metavar}\n`;
  }
  process.stdout.write(out);
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function looksLikeOption(token) {
  return token.length > 1 && token.startsWith('-') && !/^-\d/.test(token);
}

export function parseArgs(argv) {
  const prog = basename(process.argv[1] || 'test17.mjs');
  const values = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp(prog);
      process.exit(0);
    }

    let optName = token;
    let inlineValue = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        optName = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
    }

    const spec = OPTION_SPECS.find((s) => s.name === optName);
    if (!spec) {
      extras.push(token);
      continue;
    }

    let value;
    if (inlineValue !== null) {
      value = inlineValue;
    } else {
      if (i + 1 >= argv.length || looksLikeOption(argv[i + 1])) {
        fail(prog, `argument ${spec.name}: expected one argument`);
      }
      value = argv[++i];
    }

    if (spec.choices && !spec.choices.includes(value)) {
      const choiceList = spec.choices.map((c) => `'${c}'`).join(', ');
      fail(prog, `argument ${spec.name}: invalid choice: '${value}' (choose from ${choiceList})`);
    }

    values[spec.name] = value;
  }

  const missing = OPTION_SPECS.filter((s) => s.required && !(s.name in values)).map((s) => s.name);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    data: values['--data'],
    verify_iat: values['--verify_iat'],
  };
}

